/** Bralec je "ti". Imena znamenj, datumi in teme prihajajo v imenovalniku, sklon izbere sl-cases. Hiše so shranjene v mestniku, za predlogom "v". */
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const myGen = (monthYear: string) => monthYear.replace(/^\p{L}+/u, mGen);
